from hypothesis import strategies as st
from collections import deque

DIRS = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}
DLIST = ['U', 'D', 'L', 'R']


def _parse(inp):
    t = inp.split()
    H, W = int(t[0]), int(t[1])
    cells = ''.join(t[2:])
    grid = [cells[i * W:(i + 1) * W] for i in range(H)]
    return H, W, grid


def _find(grid, ch):
    for i, row in enumerate(grid):
        for j, c in enumerate(row):
            if c == ch:
                return i, j
    return None


def _move(grid, H, W, r, c, p, m):
    """p: index 0..3 into DLIST of previous move, or 4 for none (at start).
    m: index 0..3 of the move to make from (r,c). Returns new (r,c) or None."""
    cell = grid[r][c]
    if cell == 'o' and p != 4 and m != p:
        return None
    if cell == 'x' and m == p:
        return None
    dr, dc = DIRS[DLIST[m]]
    nr, nc = r + dr, c + dc
    if not (0 <= nr < H and 0 <= nc < W):
        return None
    if grid[nr][nc] == '#':
        return None
    return nr, nc


@st.composite
def gen(draw):
    h = draw(st.integers(1, 5))
    w = draw(st.integers(2, 5))
    n = h * w
    alphabet = st.sampled_from(['#', '.', '.', 'o', 'x', 'o', 'x', '#'])
    cells = draw(st.lists(alphabet, min_size=n, max_size=n))
    idx = draw(st.lists(st.integers(0, n - 1), min_size=2, max_size=2, unique=True))
    cells[idx[0]] = 'S'
    cells[idx[1]] = 'G'
    rows = [''.join(cells[i * w:(i + 1) * w]) for i in range(h)]
    return f"{h} {w}\n" + "\n".join(rows) + "\n"


